"""Generate homepage, About and problem briefs. Run build-guides.py afterward for sitemap."""
from pathlib import Path
import re,json,html
r=Path(__file__).resolve().parents[1]; p=r/'public'
old=(p/'index.html').read_text(); dialog=re.search(r'<dialog.*?</dialog>',old,re.S)[0]
nav='<header class="masthead"><a class="identity" href="/">MD Eagles</a><nav aria-label="Main navigation"><a href="/problems">Problems to solve</a><a href="/guides">Find help</a><a href="/about">About</a></nav></header>'
footer='<footer><p>Maryland Eagles Eyes · An independent publication for Maryland.</p><a href="/#subscribe">Email updates</a></footer>'
def page(title,desc,path,body,extra=''):
 schema=json.dumps({'@context':'https://schema.org','@type':'WebPage','name':title,'url':'https://mdeagles.com'+path})
 return f'<!DOCTYPE html><html lang="en-US"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | MD Eagles</title><meta name="description" content="{desc}"><link rel="canonical" href="https://mdeagles.com{path}"><meta property="og:title" content="{title} | MD Eagles"><meta property="og:description" content="{desc}"><meta property="og:url" content="https://mdeagles.com{path}"><meta property="og:type" content="website"><link rel="icon" href="/assets/eagle.svg"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{schema}</script></head><body><a class="skip-link" href="#main">Skip to content</a>{nav}<main id="main">{body}</main>{footer}{extra}</body></html>'
problems=json.loads((r/'content/problems.json').read_text())
def rows():
 return ''.join(f'<article class="guide-result" data-topic="{x["topic"]}" data-search="{html.escape(x["title"]+" "+x["summary"]+" "+x["place"]+" "+x["keywords"],quote=True)}"><p class="item-category">{x["place"]}</p><h2><a href="/problems/{x["slug"]}">{x["title"]}</a></h2><p>{x["summary"]}</p></article>' for x in problems)
about='<h1>About MD Eagles</h1><p class="lead">Maryland has people ready to make things better. We help them find a useful place to start.</p><p>Maryland Eagles Eyes is an independent publication about problems facing people in our state and practical ways to help solve them. A resident organizing neighbors, a student starting a project, a business owner or a founder should be able to find work worth taking on here.</p><h2>From a problem to a first step</h2><p>Our problem briefs bring together published evidence, the people affected, possible solutions and a small local starting point. A solution might be a service, a neighborhood effort, a better process or a tool. It does not have to be an app.</p><p>We label our proposals as ideas to test. They are not proven interventions, funded projects or open roles. Named organizations are sources or possible places to learn, not partners unless we explicitly say so.</p><h2>Evidence before promises</h2><p>Each brief links to its sources and explains where the evidence applies. We distinguish published research from our own proposals. These first briefs are based on existing reports; they are not original interviews with residents. Local conversations should shape any project before it starts.</p><h2>Help for what you are facing today</h2><p>Our <a href="/guides">resource guides</a> point readers to existing Maryland services. The <a href="/problems">problem collection</a> is for people who want to work on the gaps.</p><p><a href="/#subscribe">Subscribe for publication updates</a>.</p>'
(p/'about.html').write_text(page('About MD Eagles','Learn how MD Eagles identifies Maryland problems, examines published evidence and proposes practical local projects residents can take up.','/about',about))
home='<p class="section-kicker">Maryland Eagles Eyes</p><h1>Find a Maryland problem you can help solve.</h1><p class="lead">Understand what people are facing. Explore possible solutions. Start something useful in your city, county or across the state.</p><p><a class="primary-button" href="/problems">Browse problems to solve</a></p><div class="home-columns"><section><h2 class="section-title">Start with a problem</h2>'+rows()+'</section><aside><h2>Need help today?</h2><p>Find existing services for the situation you are facing.</p><ul><li><a href="/guides/utility-bills">Paying an energy bill</a></li><li><a href="/guides/rental-housing">Finding housing support</a></li><li><a href="/guides/career-support">Looking for work</a></li><li><a href="/guides">All resource guides</a></li></ul><h2>Who can help solve a problem?</h2><p>Neighbors. Students. Local businesses. Community groups. Founders. You do not need to be a software developer.</p><a href="/about">How we choose our starting points</a></aside></div><section class="updates-section" id="subscribe"><h2>Follow the work</h2><p>Receive updates when we publish new briefs and follow-ups.</p><button data-open-subscribe aria-haspopup="dialog" aria-controls="subscribe-dialog">Get email updates</button><noscript><p><a href="https://buttondown.com/eagles">Subscribe through Buttondown</a></p></noscript></section>'
(p/'index.html').write_text(page('Find a Maryland problem you can help solve','Explore documented Maryland problems, practical ideas residents can test and concrete first steps for local projects in their communities.','/',home,dialog+'<script src="/subscribe.js" defer></script>'))
search='<form class="directory-search" role="search" action="/problems"><div><label for="query">Search problems</label><input id="query" name="q" type="search" maxlength="160" placeholder="Try child care, business or careers"></div><div><label for="topic">Topic</label><select id="topic" name="topic"><option value="">All topics</option><option value="families">Children and families</option><option value="business">Small business</option><option value="work">Work and careers</option></select></div><button>Search</button></form><noscript><p>All problems are listed below. Search filters require JavaScript.</p></noscript><div class="results-heading"><p id="result-count" role="status" aria-live="polite">3 problems</p><a id="clear-search" href="/problems">Clear filters</a></div>'
(p/'problems.html').write_text(page('Problems to solve in Maryland','Find documented Maryland challenges and possible local projects for residents, students, community groups, business owners and builders.','/problems','<h1>Problems to solve</h1><p class="lead">Choose a problem. Understand the evidence. Find a first step you can take with people in your community.</p><p>Our first three briefs pair published evidence with ideas to test. These are starting points for local work, not funded projects or proven solutions.</p>'+search+rows()+'<section id="no-results" hidden><h2>No matching problems yet</h2><p>Try a broader search or <a href="/problems">browse all problems</a>. This collection is just beginning.</p></section>', '<script src="/find-problems.js" defer></script>'))
(p/'problems').mkdir(exist_ok=True);(p/'downloads').mkdir(exist_ok=True)
for x in problems:
 body=f'<p><a href="/problems">All problems to solve</a></p><p class="section-kicker">Problem brief · {x["place"]}</p><h1>{x["title"]}</h1><p class="lead">{x["summary"]}</p><p class="review-date">Sources reviewed November 5, 2026 · Ideas awaiting local testing</p><p><a class="primary-button" href="#start">Start with a local conversation</a></p><h2>What the evidence shows</h2><p>{x["evidence"]}</p><p>Source: <a href="{x["url"]}">{x["source"]}</a>.</p><h2>Possible solutions to test</h2><p>These are MD Eagles proposals, not projects already operating. Test the need with residents and existing services before building.</p>'
 for title,copy in x['ideas']: body+=f'<h3>{title}</h3><p>{copy}</p>'
 body+=f'<h2 id="start">Your first step</h2><p>{x["first"]}</p><h3>Who to involve</h3><p>{x["people"]}</p><h3>What to measure</h3><p>{x["measure"]}</p><h2>Build on what already exists</h2><p>Start by learning from <a href="{x["existing_url"]}">{x["existing"]}</a>. Ask what they already provide and what remains difficult. No partnership is implied.</p><h2>Take this brief with you</h2><p><a href="/downloads/{x["slug"]}.md" download>Download the project worksheet (plain text)</a></p><p>Use it to record local evidence, collaborators, costs and a small test before committing to a larger project.</p><hr><p>Facing this yourself? <a href="/guides/{x["help"]}">Find an existing service</a>.</p>'
 (p/'problems'/f'{x["slug"]}.html').write_text(page(x['title'],x['summary']+' Read the evidence, explore proposed solutions and plan a first conversation in your Maryland community.','/problems/'+x['slug'],body))
 text=f'# {x["title"]}\n\nMD Eagles | https://mdeagles.com/problems/{x["slug"]}\nReviewed November 5, 2026. Proposals, not proven solutions.\n\n## Evidence\n{x["evidence"]}\nSource: {x["url"]}\n\n## Ideas to test\n'+''.join(f'### {a}\n{b}\n\n' for a,b in x['ideas'])+f'## First step\n{x["first"]}\n\n## People to involve\n{x["people"]}\n\n## Measure\n{x["measure"]}\n\n## Existing service\n{x["existing_url"]}\n\n## Your local project notes\n- City or county:\n- What residents told us (with permission):\n- Existing services and the remaining gap:\n- Smallest useful test:\n- Who will run it:\n- Costs and required permissions:\n- How we will measure improvement:\n- Review date and reasons to stop or change direction:\n'
 (p/'downloads'/f'{x["slug"]}.md').write_text(text)
js=(p/'find-guides.js').read_text().replace("'guide' : 'guides'","'problem' : 'problems'")
(p/'find-problems.js').write_text(js)
